-- SEED ms_pacientes  (rol, usuario, paciente, cita, historia_clinica, episodio)
-- Ejecutar:  psql "<conn ms_pacientes>" -f seed_ms_pacientes.sql
BEGIN;
TRUNCATE episodio, historia_clinica, cita, paciente, usuario RESTART IDENTITY CASCADE;
DELETE FROM rol;
SELECT setval('rol_id_seq', 4, true);





COMMIT;